import { getMediaTypeFromUrl, isIgnoredLinkedAsset } from './filters-fn';
export function findLoadedMediaResources(performanceRef = performance, pageUrl = window.location.href) {
    const seen = new Set();
    return performanceRef.getEntriesByType('resource')
        .map(entry => entry.name)
        .filter(url => !isIgnoredLinkedAsset(url))
        .map(url => ({ src: url, type: getMediaTypeFromUrl(url) }))
        .filter((item) => !!item.type)
        .filter(item => {
        if (seen.has(item.src)) {
            return false;
        }
        seen.add(item.src);
        return true;
    })
        .map(item => ({
        src: item.src,
        type: item.type,
        poster: null,
        sourceKind: 'linked',
        sourceUrl: pageUrl,
        label: 'loaded resource',
    }));
}
